<template><section><form class="controls" @submit.prevent="changeGene"><label>Gene <input v-model="inputGene" maxlength="80" pattern="[A-Za-z0-9][A-Za-z0-9._-]{0,79}"/></label><button>View</button></form>
  <div class="tabs" style="flex-wrap:wrap"><button v-for="item in tabs" :aria-pressed="view===item" @click="view=item;load()">{{item}}</button></div>
  <p v-if="busy" role="status">Loading {{view.toLowerCase()}} for {{gene}}…</p><p v-if="error" role="alert">{{error}} <button @click="load">Retry</button></p>
  <template v-if="['Function','Gene Ontology','Pathways'].includes(view)"><label v-if="proteins.length>1">Reviewed human protein <select v-model="accession"><option value="">Choose a source record</option><option v-for="p in proteins" :value="p.primaryAccession">{{p.primaryAccession}} · {{p.uniProtkbId}}</option></select></label>
    <template v-if="protein"><p class="source">UniProt · {{protein.primaryAccession}} · Human reviewed record</p><div v-if="view==='Function'"><h3>{{protein.proteinDescription?.recommendedName?.fullName?.value}}</h3><p v-for="(text,i) in functions" :key="i">{{text}}</p><p v-if="!functions.length">No function description is present in this source record.</p></div>
    <table v-else><thead><tr><th>Source</th><th>Identifier</th><th>Annotation</th></tr></thead><tbody><tr v-for="ref in references" :key="ref.database+ref.id"><td>{{ref.database}}</td><td>{{ref.id}}</td><td>{{(ref.properties||[]).map(p=>p.value).join(' · ')}}</td></tr></tbody></table><a :href="'https://www.uniprot.org/uniprotkb/'+protein.primaryAccession+'/entry'" target="_blank" rel="noopener">Original UniProt record ↗</a></template>
  </template>
  <template v-else-if="rows"><div class="controls"><label>Filter source rows <input v-model="search"/></label><button @click="download">Download source result</button></div><p class="source">{{sourceLabel}} · {{rows.length}} retrieved records · {{gene}}</p>
    <p v-if="!rows.length">The source returned no records for this query. This does not establish biological absence.</p><div v-else class="heatmap-scroll"><table><thead><tr><th v-for="key in columns">{{key}}</th></tr></thead><tbody><tr v-for="(row,i) in filtered.slice(page*50,(page+1)*50)" :key="i"><td v-for="key in columns">{{display(row[key])}}</td></tr></tbody></table></div><button :disabled="page===0" @click="page--">Previous</button><span> {{page+1}} / {{Math.max(1,Math.ceil(filtered.length/50))}} </span><button :disabled="(page+1)*50>=filtered.length" @click="page++">Next</button>
  </template>
  <details><summary>Source &amp; methods</summary><p>Sources follow the PanKbase Gene Browser: reviewed human UniProt annotations, GTEx tissue statistics and BioIndex genetic evidence. Each section loads only when selected. Source rows and context fields are retained; genetic associations and HuGE scores are not proof of causality. Use the separate scBrowser and Genome Browser result tabs for cell and chromatin views.</p></details>
</section></template>
<script>
import { readPublic, readBioIndex } from './data.mjs';
import { downloadText } from './assets.mjs';
const sources={
  'Tissue specificity':{host:'https://cfde.hugeampkpnbi.org',index:'gtex-tstat',label:'GTEx tissue specificity'},
  'Expression levels':{host:'https://bioindex-dev.hugeamp.org',index:'gene-expression',label:'GTEx expression levels (PanKbase source route)'},
  'HuGE scores':{host:'https://bioindex.hugeamp.org',index:'huge',label:'HuGE scores'},
  'Common variants':{host:'https://bioindex.hugeamp.org',index:'gene-associations',label:'Common variant associations'},
  'Rare variants':{host:'https://bioindex.hugeamp.org',index:'gene-associations-52k',label:'Rare variant associations (52k source)'},
};
export default{props:['context'],data:()=>({gene:'',inputGene:'',view:'Function',tabs:['Function','Gene Ontology','Pathways',...Object.keys(sources)],proteins:[],accession:'',rows:null,error:'',busy:false,serial:0,search:'',page:0}),
  computed:{protein(){return this.proteins.find(p=>p.primaryAccession===this.accession);},functions(){return (this.protein?.comments||[]).filter(c=>c.commentType==='FUNCTION').flatMap(c=>(c.texts||[]).map(t=>t.value));},references(){return (this.protein?.uniProtKBCrossReferences||[]).filter(r=>this.view==='Gene Ontology'?r.database==='GO':['Reactome','KEGG','WikiPathways'].includes(r.database));},columns(){return [...new Set((this.rows||[]).flatMap(row=>Object.keys(row)))];},filtered(){return(this.rows||[]).filter(row=>JSON.stringify(row).toLowerCase().includes(this.search.toLowerCase()));},sourceLabel(){return sources[this.view]?.label;}},
  watch:{search(){this.page=0;}},mounted(){this.gene=this.context.geneSymbol;this.inputGene=this.gene;this.load();},
  methods:{display(value){return value===null||value===undefined?'Not reported':typeof value==='object'?JSON.stringify(value):String(value);},changeGene(){const gene=this.inputGene.trim();if(!/^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/.test(gene)){this.error='Enter a valid gene symbol.';return;}this.gene=gene;this.proteins=[];this.accession='';this.load();},async load(){const token=++this.serial;this.error='';this.busy=true;this.rows=null;this.page=0;try{if(['Function','Gene Ontology','Pathways'].includes(this.view)){if(!this.proteins.length){const query=encodeURIComponent(`(gene_exact:${this.gene}) AND (organism_id:9606) AND (reviewed:true)`);const response=JSON.parse(await readPublic('https://rest.uniprot.org/uniprotkb/search?query='+query+'&format=json&size=25'));if(token!==this.serial)return;this.proteins=response.results||[];this.accession=this.proteins.length===1?this.proteins[0].primaryAccession:'';if(!this.proteins.length)this.error='No reviewed human UniProt record was returned.';}}else{const source=sources[this.view],response=await readBioIndex(source.host+'/api/bio/query/'+source.index+'?q='+encodeURIComponent(this.gene));if(!Array.isArray(response.data))throw new Error('The source returned an unexpected result format.');if(token===this.serial)this.rows=response.data;}}catch(e){if(token===this.serial)this.error=e.message+' Available graph evidence is preserved.';}finally{if(token===this.serial)this.busy=false;}},download(){downloadText(JSON.stringify({gene:this.gene,source:sources[this.view],rows:this.rows},null,2),this.gene+'-'+this.view.replaceAll(' ','-')+'.json','application/json');}},
};
</script>
